// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    uint cumulative;

    function setUp() public {
        c = new EtherLotto();
        cumulative = 0;
    }

    function testFuzz_property(uint8 run) public {
        vm.assume(run >= 1 && run <= 10);

        bool lastWon = false;
        for (uint i = 0; i < run; i++) {
            uint ticket = 10;
            address player = address(uint160(uint(keccak256(abi.encodePacked(this, i)))));
            vm.deal(player, ticket);
            vm.prank(player);
            c.play{value: ticket}();

            cumulative++;

            uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
            if (random == 0) {
                lastWon = true;
            } else {
                lastWon = false;
            }
        }

        uint expectedPot;
        if (lastWon) {
            expectedPot = 0;
        } else {
            expectedPot = cumulative * 10;
        }

        uint actualPot = c.pot();
        assertTrue(actualPot == expectedPot);
    }
}
